#!/usr/bin/env node
/**
 * gen-registry.mjs — site-blueprint.csv -> src/data/site.ts + posts.ts + routes.ts
 *
 *   node scripts/gen-registry.mjs [research/site-blueprint.csv]
 *   node scripts/gen-registry.mjs --check
 *
 * --check exits 1 when a generated file is missing or older than the CSV, or when a built
 * src/pages route is absent from the registry. Node 20+, stdlib only.
 */
import fs from 'node:fs';
import path from 'node:path';
import { parseCsv } from './lib/csv.mjs';   // the ONE RFC-4180 parser (Task G1.2 Step 2b)

const argv = process.argv.slice(2);
const CHECK = argv.includes('--check');
const CSV = argv.find(a => !a.startsWith('--')) || 'research/site-blueprint.csv';
const OUT = 'src/data';
const ex = p => { try { fs.accessSync(p); return true; } catch { return false; } };
const rd = p => fs.readFileSync(p, 'utf8').replace(/^\uFEFF/, '');
if (!ex(CSV)) { console.error(`FAIL: ${CSV} missing.`); process.exit(1); }

/* RFC-4180: IMPORTED from ./lib/csv.mjs (Task G1.2 Step 2b) — ONE parser, ONE behaviour.
   parseCsv() returns [{cells, quoted}]; this script needs only the cells. Re-declaring a
   second parser here, or splitting on ',', is the CONS2-12 / curio-2.7 defect. */
const table = parseCsv(rd(CSV)).map((r) => r.cells);
const head = table[0];
const rows = table.slice(1).map(c => Object.fromEntries(head.map((h, i) => [h, (c[i] || '').trim()])));
const split = s => (s || '').split('|').map(x => x.trim()).filter(Boolean);
const routeFiles = () => {
  const out = [];
  (function walk(d) { if (!ex(d)) return; for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else out.push(p.replace(/\\/g, '/')); } })('src/pages');
  return out.filter(p => /\.(astro|md)$/.test(p) && !/\[.+\]/.test(p)).map(p => {
    let r = p.replace(/^src\/pages/, '').replace(/\.(astro|md)$/, '');
    if (r === '/404') return '/404';
    if (r === '/index') return '/';
    r = r.replace(/\/index$/, '');
    return r.endsWith('/') ? r : r + '/';
  });
};

// kit-manifest.json declares src/data/site.ts and src/data/posts.ts `kind: seed` - the
// PROJECT owns them, and site-kit.py refuses to overwrite them on update. This generator
// overwrote both anyway. On chihuahua.sg, src/data/site.ts is the hand-authored business-
// values module every page imports as `{ site }`; overwriting it with the route registry
// removed that export and broke the build with no warning. Where a name collides, the
// registry moves aside rather than destroying what is already there.
const BANNER = 'GENERATED by scripts/gen-registry.mjs';
const ownedByProject = (f) => {
  const abs = `${OUT}/${f}`;
  if (!fs.existsSync(abs)) return false;
  const t = fs.readFileSync(abs, 'utf8');
  return t.trim() !== '' && !t.includes(BANNER);
};
const siteOwned = ownedByProject('site.ts');
const REG_FILE = siteOwned ? 'registry.ts' : 'site.ts';
const REG_MOD = siteOwned ? './registry' : './site';

if (CHECK) {
  // Only the files THIS generator writes can be stale against the CSV. A project-owned
  // seed is not stale, it is not ours - calling it stale made check:registry unpassable
  // on any project that owns its own src/data/site.ts.
  const files = [REG_FILE, 'posts.ts', 'routes.ts']
    .filter((f) => !ownedByProject(f) || f === REG_FILE)
    .map((f) => `${OUT}/${f}`);
  const csvTime = fs.statSync(CSV).mtimeMs;
  let fails = 0;
  const report = [];
  for (const f of files) {
    const ok = ex(f) && fs.statSync(f).mtimeMs >= csvTime;
    if (!ok) fails++;
    report.push([f, ex(f) ? (fs.statSync(f).mtimeMs >= csvTime ? 'fresh' : 'STALE') : 'MISSING', ok ? 'PASS' : 'FAIL']);
  }
  // TRAILING SLASH (2026-09-05). routeFiles() emits the built route WITH a trailing
  // slash ("/water-damage/"); the CSV's url_slug is written without one. The raw
  // Set.has() therefore matched only "/", and the gate reported 1/91 routes missing a
  // row on a site whose every route HAS one. Compare both sides normalised.
  const norm = (r) => (String(r || '').replace(/\/+$/, '') || '/');
  const slugs = new Set(rows.map(r => norm(r.url_slug)));
  // NOT CONTENT ROUTES (2026-09-05): the 404 page and the kit's /_patterns/ component
  // gallery are chrome, not blueprint rows. Demanding a row for them made the gate
  // unpassable on every project that ships either.
  const NON_CONTENT = /^\/(404|_)/;
  const built = routeFiles().filter(r => !NON_CONTENT.test(r));
  const missing = built.filter(r => !slugs.has(norm(r)));
  report.push(['built routes present in the registry', `${built.length - missing.length}/${built.length}`, missing.length ? 'FAIL' : 'PASS']);
  if (missing.length) fails++;
  console.log('check'.padEnd(44) + 'value'.padEnd(12) + 'result');
  console.log('-'.repeat(68));
  for (const [n, v, r] of report) console.log(String(n).padEnd(44) + String(v).padEnd(12) + r);
  if (missing.length) console.log('\nroutes without a row: ' + missing.join(', '));
  console.log(fails ? 'REGISTRY_FAIL' : `REGISTRY_OK routes=${routeFiles().length} rows=${rows.length}`);
  process.exit(fails ? 1 : 0);
}

/* ---------- generate ---------- */
fs.mkdirSync(OUT, { recursive: true });
const esc = s => String(s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const toRoute = r => `  { slug: '${esc(r.url_slug)}', title: '${esc(r.title)}', h1: '${esc(r.h1)}', tier: '${esc(r.page_tier)}', section: '${esc(r.section_class)}', silo: '${esc(r.silo)}', level: '${esc(r.hub_or_node)}', pageType: '${esc(r.page_type)}', parent: '${esc(r.parent)}', children: [${split(r.link_children).map(c => `'${esc(c)}'`).join(', ')}], schema: [${split(r.schema).map(c => `'${esc(c)}'`).join(', ')}], formId: '${esc(r.form_id)}', og: '/og${r.url_slug === '/' ? '/home' : r.url_slug.replace(/\/$/, '')}.png', buildOrder: ${Number(r.build_order) || 0}, targetKeyword: '${esc(r.target_keyword)}', linkRoot: '${esc(r.link_root)}', linkSeed: '${esc(r.link_seed)}', linkNode: '${esc(r.link_node)}' }`;

const siteTs = `// GENERATED by scripts/gen-registry.mjs from ${CSV} — DO NOT EDIT BY HAND.
// Hand-typed route/hub/post arrays in components are forbidden; run \`npm run gen:registry\`.
export interface Route {
  slug: string; title: string; h1: string; tier: string; section: string; silo: string;
  level: string; pageType: string; parent: string; children: string[]; schema: string[];
  formId: string; og: string; buildOrder: number; targetKeyword: string;
  // The blueprint's Root-Seed-Node contract, carried through so a component can render
  // it as REAL in-content links. Recording it in the CSV and never emitting it is how a
  // link contract passes validation and moves no authority.
  linkRoot: string; linkSeed: string; linkNode: string;
}
export const ROUTES: Route[] = [
${rows.map(toRoute).join(',\n')}
];
export const BY_SLUG: Record<string, Route> = Object.fromEntries(ROUTES.map(r => [r.slug, r]));
export const HUBS: Route[] = ROUTES.filter(r => r.level === 'L2');
export const MONEY_HUBS: Route[] = HUBS.filter(r => r.tier === 'core');
export const UTILITY: Route[] = ROUTES.filter(r => r.tier === 'utility');
export const MONETIZATION: Route[] = ROUTES.filter(r => r.tier === 'monetization');
export const NAV = { header: MONEY_HUBS.slice(0, 4), blog: BY_SLUG['/blog/'] ?? null, footer: [...HUBS, ...UTILITY, ...MONETIZATION] };
export const childrenOf = (slug: string): Route[] => (BY_SLUG[slug]?.children ?? []).map(s => BY_SLUG[s]).filter(Boolean) as Route[];
export const inSitemap = (r: Route): boolean => r.slug !== '/404' && !/thank-you/.test(r.slug);
`;
const cfgTxt = fs.existsSync('config/project-config.md')
  ? fs.readFileSync('config/project-config.md', 'utf8') : '';
const cfg = (k, d = '') => {
  const m = cfgTxt.match(new RegExp('^' + k + ':\s*(.*)$', 'm'));
  if (!m) return d;
  // project-config comment convention: value ends at 2+ spaces followed by "#"
  const v = m[1].split(/\s{2,}#/)[0].trim();
  return (!v || /^(none|n\/a)$/i.test(v)) ? d : v;
};
// Conversion destination for the header CTA. Derived, never assumed.
// GA4 key events, derived from config/forms.json.
let ga4Events = [];
try {
  const reg = JSON.parse(fs.readFileSync('config/forms.json', 'utf8'));
  ga4Events = [...new Set((reg.forms || []).map(f => f.ga4_event).filter(Boolean))];
} catch { ga4Events = []; }
if (!ga4Events.includes('cta_click')) ga4Events.push('cta_click');

const GOAL = (cfg('PRIMARY_CTA_GOAL') || 'form').toLowerCase();
const formRoutes = rows.filter(r => (r.form_id || '').trim());
const utilityForm = formRoutes.find(r => (r.page_tier || '') === 'utility');
const pitchRoute = rows.find(r => r.url_slug === '/write-for-us/');
const ctaHref = cfg('CTA_HREF')
  || (GOAL === 'pitch' && pitchRoute ? '/write-for-us/' : '')
  || (utilityForm ? utilityForm.url_slug : '')
  || (formRoutes.length ? formRoutes[0].url_slug : '/contact/');

const sameAs = cfg('SOCIAL_PROFILES').split(',').map(x => x.trim())
  .filter(x => /^https?:\/\//.test(x));
const identity = `
// ── SITE identity (contracts §12). GENERATED from config/project-config.md.
// The author entity is defined ONCE here and injected by the layout; pages never set
// schema.author. Change a value in project-config.md and re-run \`npm run gen:registry\`.
export interface NavItem { label: string; href: string; children?: NavItem[] }
export const SITE = {
  name: ${JSON.stringify(cfg('BUSINESS_NAME'))},
  slogan: ${JSON.stringify(cfg('SLOGAN'))},
  description: ${JSON.stringify(cfg('BUSINESS_TYPE'))},
  domain: ${JSON.stringify(cfg('DOMAIN'))},
  origin: ${JSON.stringify(cfg('DOMAIN'))},
  editorialEmail: ${JSON.stringify(cfg('EDITORIAL_EMAIL'))},
  email: ${JSON.stringify(cfg('EDITORIAL_EMAIL'))},
  archetype: ${JSON.stringify(cfg('SITE_ARCHETYPE'))},
  authorModel: ${JSON.stringify(cfg('AUTHOR_MODEL'))},
  imagePolicy: ${JSON.stringify(cfg('IMAGE_POLICY'))},
  spelling: ${JSON.stringify(cfg('SPELLING'))},
  locale: ${JSON.stringify(cfg('LANGUAGE', 'en'))},
  country: ${JSON.stringify(cfg('COUNTRY'))},
  legalEntity: ${JSON.stringify(cfg('LEGAL_ENTITY'))},
  ownerName: ${JSON.stringify(cfg('OWNER_NAME'))},
  ownerCredentials: ${JSON.stringify(cfg('OWNER_CREDENTIALS'))},
  founded: ${JSON.stringify(cfg('FOUNDED') === 'omit' ? '' : cfg('FOUNDED'))},
  responseTime: ${JSON.stringify(cfg('FORM_SUCCESS_MESSAGE'))},
  alternateName: '', licence: '', phone: '', address: '', geo: '',
  // kit fix: these three were hard-coded empty, so the rank-and-rent-pretenant schema row
  // (Organization + areaServed + contactPoint + hoursAvailable + knowsAbout) could never be
  // satisfied - schema.ts reads SITE.areaServed / SITE.hoursAvailable and got ''.
  areaServed: ${JSON.stringify(cfg('SERVICE_AREAS'))},
  hoursAvailable: ${JSON.stringify(cfg('BUSINESS_HOURS'))},
  localBusinessType: '', hasSearchPage: false,
  // Organization.sameAs[] — REQUIRED for a publisher, never an invented handle.
  // Empty here means the owner has not supplied the profile URLs yet; the launch gate blocks.
  sameAs: ${JSON.stringify(sameAs)} as string[],
} as const;
// Nav labels are SHORT: an H1 is written for the page, not for a nav bar.
// kit fix: the 1.0.0 map named only the kit's example slugs, so every real project fell
// through to r.title and shipped a nav of 60-character page titles. Labels now derive from
// the route: an explicit override, else the target keyword title-cased, else a trimmed title.
const NAV_LABEL: Record<string, string> = {
  '/pricing/': 'Pricing', '/compare/': 'Comparisons', '/reviews/': 'Reviews',
  '/guides/': 'Guides', '/blog/': 'Guides',
};
const NAV_MAX = 22;
function navLabel(r: Route): string {
  if (NAV_LABEL[r.slug]) return NAV_LABEL[r.slug];
  const kw = (r.targetKeyword || '').trim();
  if (kw && kw.length <= NAV_MAX) {
    // Acronyms stay uppercase; the rest is sentence case. A token map rather than a regex,
    // because the escape sequences in a generated file are one more thing to get wrong.
    const CAPS = new Set(['hdb', 'bto', 'sg', 'ocs', 'ac', 'id']);
    return kw.split(' ')
      .map((w, i) => CAPS.has(w.toLowerCase()) ? w.toUpperCase()
        : i === 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w)
      .join(' ');
  }
  const head = (r.title || '').split(/[:|]/)[0].trim();
  return head.length <= NAV_MAX ? head : head.slice(0, NAV_MAX).trim();
}
export const NAV_MENU: NavItem[] = [...NAV.header, ...(NAV.blog ? [NAV.blog] : [])]
  .map(r => ({ label: navLabel(r), href: r.slug }));
export const SITE_ARCHETYPE = SITE.archetype;
// AUTHOR_MODEL and SILO_ITEMS are consumed by src/lib/schema.ts (Organization.author and
// Organization.knowsAbout). They are EMITTED here rather than typed in site.ts, because
// site.ts is generated and a hand-added export is destroyed on the next run.
export const AUTHOR_MODEL = ${JSON.stringify(cfg('AUTHOR_MODEL', 'organization'))};
// SILO_ITEMS: the project-config comma list when set, else the silo hub titles from the
// blueprint, so knowsAbout always names what the site actually covers.
export const SILO_ITEMS: string[] = ${JSON.stringify(
  (cfg('SILO_ITEMS', '') || '').split(',').map(s => s.trim()).filter(Boolean)
)}.length
  ? ${JSON.stringify((cfg('SILO_ITEMS', '') || '').split(',').map(s => s.trim()).filter(Boolean))}
  : HUBS.filter(r => r.tier === 'core').map(r => r.title);
// Monetization CTAs live in the header BUTTON slot, never as a plain nav item (contracts §14).
// kit fix: href was hard-coded to '/write-for-us/', a national-publisher route. On every
// other archetype that is a 404 behind the header's primary button. The destination is now
// DERIVED: the conversion route named by PRIMARY_CTA_GOAL, taken from the blueprint.
// kit fix: src/lib/track.ts has imported GA4_EVENTS from here since 1.0.0 and the generator
// never emitted it, so any project with a client-side track() call failed the vite client
// build. Names are EXACTLY the form registry's ga4_event values (contracts: never a
// hard-coded whatsapp_click / form_submit / cta_click list), plus cta_click only when a
// [data-cta] element exists in the component library.
export const GA4_EVENTS = ${JSON.stringify(ga4Events)} as const;
export const PRIMARY_CTA = { label: ${JSON.stringify(cfg('PRIMARY_CTA', 'Get in touch'))}, href: ${JSON.stringify(ctaHref)} };
export const FOOTER = {
  legal: UTILITY.filter(r => r.slug !== '/' && r.slug !== '/404').map(r => ({ label: r.title, href: r.slug })),
  hubs: HUBS.map(r => ({ label: r.title, href: r.slug })),
  monetization: MONETIZATION.map(r => ({ label: r.title, href: r.slug })),
  note: ${JSON.stringify(cfg('SITE_WIDE_NOTICE'))},
};
`;
if (siteOwned) {
  console.log('NOTE src/data/site.ts is a project-authored seed — writing the route registry');
  console.log(`     to src/data/${REG_FILE} instead, and re-exporting it from routes.ts.`);
}
fs.writeFileSync(`${OUT}/${REG_FILE}`, siteTs + identity, 'utf8');

const posts = rows.filter(r => r.section_class === 'outer' && r.page_tier === 'outer');
if (!ownedByProject('posts.ts')) fs.writeFileSync(`${OUT}/posts.ts`, `// GENERATED by scripts/gen-registry.mjs — DO NOT EDIT BY HAND.
import type { Route } from '${REG_MOD}';
import { ROUTES } from '${REG_MOD}';
export const POSTS: Route[] = ROUTES.filter(r => r.section === 'outer' && r.tier === 'outer');
export const POSTS_BY_SILO: Record<string, Route[]> = POSTS.reduce((acc, p) => { (acc[p.silo] ||= []).push(p); return acc; }, {} as Record<string, Route[]>);
`, 'utf8');

fs.writeFileSync(`${OUT}/routes.ts`, `// GENERATED by scripts/gen-registry.mjs — DO NOT EDIT BY HAND.
export type { Route } from '${REG_MOD}';
export { ROUTES, BY_SLUG, HUBS, MONEY_HUBS, UTILITY, MONETIZATION, NAV, childrenOf, inSitemap } from '${REG_MOD}';
export const ROUTE_SLUGS: string[] = [
${rows.map(r => `  '${esc(r.url_slug)}'`).join(',\n')}
];
`, 'utf8');

/* ---------- 1:1 redirect rules for moved routes ---------- */
let moved = 0;
const movedRules = [];
for (const r of rows) {
  const m = (r.notes || '').match(/moved-from:\s*(\/[^\s,;]*\/)/);
  if (!m) continue;
  movedRules.push(`${m[1]}  ${r.url_slug}  301`);
  const noSlash = m[1].replace(/\/$/, '');
  if (noSlash) movedRules.push(`${noSlash}  ${r.url_slug}  301`);
  moved++;
}
if (movedRules.length) {
  fs.mkdirSync('public', { recursive: true });
  let red = ex('public/_redirects') ? rd('public/_redirects') : '';
  const fresh = movedRules.filter(l => !red.includes(l.split(/\s+/)[0] + '  '));
  if (fresh.length) {
    if (red && !red.endsWith('\n')) red += '\n';
    red += `\n# --- route moves (generated ${new Date().toISOString().slice(0, 10)}; specific rules before splats) ---\n` + fresh.join('\n') + '\n';
    fs.writeFileSync('public/_redirects', red, 'utf8');
  }
}
console.log('output'.padEnd(28) + 'value'.padEnd(12) + 'result');
console.log('-'.repeat(52));
console.log(`src/data/${REG_FILE}`.padEnd(28) + String(rows.length).padEnd(12) + 'PASS');
console.log('src/data/posts.ts'.padEnd(28) + String(posts.length).padEnd(12) + 'PASS');
console.log('src/data/routes.ts'.padEnd(28) + String(rows.length).padEnd(12) + 'PASS');
console.log('moved-from redirect rules'.padEnd(28) + String(moved).padEnd(12) + 'PASS');
console.log(`\nREGISTRY_OK routes=${rows.length} rows=${rows.length}`);
// contracts section-1b, generator form: a generator that wrote NOTHING has
// silently done nothing, and the build then fails somewhere else entirely.
console.log(`gen-registry: wrote=${rows.length}`);
